'use strict';
const fs=require('node:fs'),fsp=require('node:fs/promises'),crypto=require('node:crypto'),path=require('node:path');
const NotesMedia=require('../NotesRoom/media'),NotesLinks=require('../NotesRoom/links');
const types={'.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.gif':'image/gif','.webp':'image/webp','.webm':'audio/webm','.ogg':'audio/ogg','.mp3':'audio/mpeg','.wav':'audio/wav','.m4a':'audio/mp4','.mp4':'audio/mp4'};
const maxPackage=36*1024*1024,maxMedia=24*1024*1024,maxItems=50,maxFile=20*1024*1024;
const key=item=>JSON.stringify([item.path,item.attachment||null]);
function references(body,relative,fail){const parsed=NotesMedia.references(body),refs=new Map();for(const item of parsed.items){relative(item.path);refs.set(key(item),item);}if(refs.size>maxItems)throw fail(413,'A note bundle supports at most 50 distinct media references.');let fenced=false;for(const line of parsed.lines){if(/^```/.test(line)){fenced=!fenced;continue;}if(!fenced&&/!\[[^\]]*\]\(/.test(line)&&!NotesMedia.parseLine(line))throw fail(400,'The note contains an unsupported image link. Only NotesRoom image attachments can be included in a bundle.');}return {parsed,refs};}
async function readMedia(file,expected,fail){const before=await fsp.lstat(file);if(before.isSymbolicLink()||!before.isFile()||before.size<1||before.size>maxFile||(expected&&before.size!==expected))throw fail(413,'Note bundle media must be regular files up to 20 MiB.');const handle=await fsp.open(file,fs.constants.O_RDONLY|(fs.constants.O_NOFOLLOW||0));try{const stat=await handle.stat();if(!stat.isFile()||stat.dev!==before.dev||stat.ino!==before.ino||stat.size!==before.size)throw fail(409,'Note media changed while packaging.');const data=await handle.readFile(),after=await handle.stat();if(data.length!==stat.size||after.size!==stat.size||after.mtimeMs!==stat.mtimeMs)throw fail(409,'Note media changed while packaging.');return data;}finally{await handle.close();}}
function warnings(note){const out=[];if(NotesLinks.find(note.body).ids.length)out.push('Links to other notes keep their original IDs; the linked notes are not included.');return out;}
async function create(note,{existing,noteAttachments,relative,fail}){const {refs}=references(note.body,relative,fail),assets=[];let total=0;for(const ref of refs.values()){let file,expected,hash;const mime=types[path.extname(ref.path).toLowerCase()];if(!mime)throw fail(415,'Unsupported note media.');if(ref.attachment){const saved=await noteAttachments.entry(ref.attachment);if(saved.info.mime_type!==mime)throw fail(415,'Note media type does not match its attachment.');file=saved.file;expected=saved.info.bytes;hash=saved.info.sha256;}else file=await existing(ref.path);const data=await readMedia(file,expected,fail);total+=data.length;if(total>maxMedia)throw fail(413,'A note bundle supports at most 24 MiB of media.');const sha=crypto.createHash('sha256').update(data).digest('hex');if(hash&&sha!==hash)throw fail(409,'A protected note attachment failed its integrity check.');assets.push({path:ref.path,attachment:ref.attachment||null,mime_type:mime,bytes:data.length,sha256:sha,data:data.toString('base64')});}return {format:'roomsuite.note-bundle',version:1,note:{title:note.title,body:note.body,folder:note.folder,tags:note.tags},assets,warnings:warnings(note)};}
function validate(bundle,{relative,noteValues,fail}){if(!bundle||bundle.format!=='roomsuite.note-bundle'||bundle.version!==1||!Array.isArray(bundle.assets)||bundle.assets.length>maxItems)throw fail(400,'Unsupported or invalid note bundle.');const note=noteValues(bundle.note),{parsed,refs}=references(note.body,relative,fail),assets=new Map();let total=0;for(const item of bundle.assets){if(!item||typeof item.path!=='string'||(item.attachment!==null&&typeof item.attachment!=='string')||typeof item.data!=='string'||!/^[0-9a-f]{64}$/.test(item.sha256||'')||!Number.isSafeInteger(item.bytes)||item.bytes<1||item.bytes>maxFile)throw fail(400,'Invalid note bundle media.');relative(item.path);const id=key(item),ref=refs.get(id),mime=types[path.extname(item.path).toLowerCase()];if(!ref||assets.has(id)||!mime||item.mime_type!==mime||item.data.length!==Math.ceil(item.bytes/3)*4||!/^[A-Za-z0-9+/]*={0,2}$/.test(item.data))throw fail(400,'Invalid or unexpected note bundle media.');const data=Buffer.from(item.data,'base64');if(data.length!==item.bytes||data.toString('base64')!==item.data||crypto.createHash('sha256').update(data).digest('hex')!==item.sha256)throw fail(400,'Note bundle media failed its integrity check.');total+=data.length;if(total>maxMedia)throw fail(413,'A note bundle supports at most 24 MiB of media.');assets.set(id,{ref,data});}if(assets.size!==refs.size)throw fail(400,'The note bundle is missing media.');return {note,parsed,assets,warnings:warnings(note)};}
module.exports={create,validate,key,maxPackage,maxMedia,maxItems};
